80	        Collection<Owner> owners;
81	        if (lastName != null) {
82	            owners = this.clinicService.findOwnerByLastName(lastName);
83	        } else {
84	            owners = this.clinicService.findAllOwners();
85	        }
86	        if (owners.isEmpty()) {
87	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
88	        }
89	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
90	    }
91	
92	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
93	    @Override
94	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
95	        Owner owner = this.clinicService.findOwnerById(ownerId);
96	        if (owner == null) {
97	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
98	        }
99	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
100	    }
101	
102	    /** Matches a syntactically valid email address: a local part and domain (with at least one dot)
103	     *  separated by '@', none of which contain whitespace or a second '@'. */
104	    private static final java.util.regex.Pattern EMAIL_PATTERN =
105	        java.util.regex.Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");
106	
107	    /**
108	     * Normalize the optional email: absent stays absent; when present it must be syntactically
109	     * valid and is lower-cased. Returns {@code false} if present but invalid.
110	     */
111	    private boolean normalizeEmail(Owner owner) {
112	        String email = owner.getEmail();
113	        if (email == null || email.isEmpty()) {
114	            owner.setEmail(null);
115	            return true;
116	        }
117	        if (!EMAIL_PATTERN.matcher(email).matches()) {
118	            return false;
119	        }
120	        owner.setEmail(email.toLowerCase(java.util.Locale.ROOT));
121	        return true;
122	    }
123	
124	    /**
125	     * Normalize a telephone number to E.164 form: strip spaces, dashes and brackets; keep a leading
126	     * '+' and country code when present, otherwise assume country code '+61' and drop a single leading
127	     * '0' from the national digits. The result must have 8 to 15 digits after the '+'.
128	     *
129	     * @return the E.164 string (e.g. {@code +61412345678}), or {@code null} when the input cannot form
130	     *         a valid E.164 number.
131	     */
132	    private static String toE164(String raw) {
133	        if (raw == null) {
134	            return null;
135	        }
136	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
137	        String digits;
138	        if (cleaned.startsWith("+")) {
139	            digits = cleaned.substring(1);
140	        } else {
141	            if (cleaned.startsWith("0")) {
142	                cleaned = cleaned.substring(1);
143	            }
144	            digits = "61" + cleaned;
145	        }
146	        if (!digits.matches("\\d{8,15}")) {
147	            return null;
148	        }
149	        return "+" + digits;
150	    }
151	
152	    /**
153	     * Validate the national-number length of a canonical E.164 string against its country code:
154	     * '+61' (Australia) requires 9 national digits and '+1' (NANP) requires 10. Numbers carrying any
155	     * other country code are not length-checked here and are accepted. Expects the '+'-prefixed digit
156	     * string produced by {@link #toE164}.
157	     *
158	     * @return {@code true} when the national-number length is correct for the country code.
159	     */
160	    private static boolean hasValidNationalLength(String e164) {
161	        String digits = e164.substring(1);
162	        if (digits.startsWith("61")) {
163	            return digits.length() - 2 == 9;
164	        }
165	        if (digits.startsWith("1")) {
166	            return digits.length() - 1 == 10;
167	        }
168	        return true;
169	    }
170	
171	    /**
172	     * Build the customer code {@code <REGION>-<HASH8>}: REGION is the region code derived from the
173	     * owner's postcode (NSW/VIC/QLD, or {@code UNKNOWN} when the postcode is absent or in no known
174	     * range) and HASH8 is the first 8 upper-case hex characters of SHA-256 over the concatenation of
175	     * the owner's normalized (E.164) telephone and last name (e.g. {@code NSW-3F9A0C17}). No sequence
176	     * numbers are used, so the code is a pure function of the owner's region-and-hash identity.
177	     */
178	    private String customerCodeFor(Owner owner) {
179	        String region = ownerMapper.regionFromPostcode(owner);
180	        if (region == null) {
181	            region = "UNKNOWN";
182	        }
183	        return region + "-" + hash8(owner.getTelephone(), owner.getLastName());
184	    }
185	
186	    /**
187	     * First 8 upper-case hex characters (the first 4 bytes) of SHA-256 over
188	     * {@code normalizedTelephone + lastName}, treating a {@code null} component as empty.
189	     */
190	    private static String hash8(String normalizedTelephone, String lastName) {
191	        String input = (normalizedTelephone == null ? "" : normalizedTelephone)
192	            + (lastName == null ? "" : lastName);
193	        try {
194	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
195	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
196	            StringBuilder sb = new StringBuilder(8);
197	            for (int i = 0; i < 4; i++) {
198	                sb.append(String.format("%02X", digest[i]));
199	            }
200	            return sb.toString();
201	        }
202	        catch (java.security.NoSuchAlgorithmException e) {
203	            throw new IllegalStateException(e);
204	        }
205	    }
206	
207	    /** Common street-type abbreviations expanded during address normalization. */
208	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
209	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
210	
211	    /**
212	     * Normalize an address: {@code null} becomes empty, surrounding whitespace is trimmed, internal
213	     * runs of whitespace are collapsed to a single space, the value is upper-cased and common
214	     * street-type abbreviations (ST-&gt;STREET, RD-&gt;ROAD, AVE-&gt;AVENUE) are expanded token by token.
215	     */
216	    private static String normalizeAddress(String value) {
217	        if (value == null) {
218	            return "";
219	        }
220	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
221	        if (collapsed.isEmpty()) {
222	            return "";
223	        }
224	        String[] tokens = collapsed.split(" ");
225	        StringBuilder sb = new StringBuilder(collapsed.length());
226	        for (int i = 0; i < tokens.length; i++) {
227	            if (i > 0) {
228	                sb.append(' ');
229	            }
230	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
231	        }
232	        return sb.toString();
233	    }
234	
235	    /**
236	     * Normalize a value for household-duplicate comparison: {@code null} becomes empty, surrounding
237	     * whitespace is trimmed, internal runs of whitespace are collapsed to a single space and the result
238	     * is lower-cased, so the comparison is case-insensitive with collapsed whitespace.
239	     */
240	    private static String normalizeForHousehold(String value) {
241	        if (value == null) {
242	            return "";
243	        }
244	        return value.trim().replaceAll("\\s+", " ").toLowerCase(java.util.Locale.ROOT);
245	    }
246	
247	    /**
248	     * Return the owners that already share this owner's household, i.e. have the same last name and
249	     * address compared case-insensitively with collapsed whitespace.
250	     */
251	    private List<Owner> householdMembers(Owner owner) {
252	        String lastName = normalizeForHousehold(owner.getLastName());
253	        String address = normalizeForHousehold(owner.getAddress());
254	        List<Owner> members = new java.util.ArrayList<>();
255	        for (Owner existing : this.clinicService.findAllOwners()) {
256	            if (normalizeForHousehold(existing.getLastName()).equals(lastName)
257	                && normalizeForHousehold(existing.getAddress()).equals(address)) {
258	                members.add(existing);
259	            }
260	        }
261	        return members;
262	    }
263	
264	    /**
265	     * Return {@code true} when another owner already shares this owner's household, i.e. has the same
266	     * last name and address compared case-insensitively with collapsed whitespace.
267	     */
268	    private boolean sharesHouseholdWithExisting(Owner owner) {
269	        return !householdMembers(owner).isEmpty();
270	    }
271	
272	    /**
273	     * Count the existing owners that share this owner's first name and last name, compared
274	     * case-insensitively. Used to populate {@code namesakeCount} on create (before this owner is saved).
275	     */
276	    private int namesakeCount(Owner owner) {
277	        String firstName = owner.getFirstName();
278	        String lastName = owner.getLastName();
279	        int count = 0;
280	        for (Owner existing : this.clinicService.findAllOwners()) {
281	            if (firstName != null && lastName != null
282	                && firstName.equalsIgnoreCase(existing.getFirstName())
283	                && lastName.equalsIgnoreCase(existing.getLastName())) {
284	                count++;
285	            }
286	        }
287	        return count;
288	    }
289	
290	    /**
291	     * A stable, shared household identifier derived from the normalized last name and address, so every
292	     * owner in the same household deterministically resolves to the same value.
293	     */
294	    private static String householdIdFor(Owner owner) {
295	        String key = normalizeForHousehold(owner.getLastName()) + "|" + normalizeForHousehold(owner.getAddress());
296	        try {
297	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
298	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
299	            StringBuilder sb = new StringBuilder(24);
300	            for (int i = 0; i < 12; i++) {
301	                sb.append(String.format("%02X", digest[i]));
302	            }
303	            return sb.toString();
304	        }
305	        catch (java.security.NoSuchAlgorithmException e) {
306	            throw new IllegalStateException(e);
307	        }
308	    }
309	
310	    /** Region -&gt; inclusive 4-digit postcode range {low, high}. */
311	    private static final java.util.Map<String, int[]> REGION_POSTCODE_RANGES = java.util.Map.of(
312	        "NSW", new int[] {2000, 2099},
313	        "VIC", new int[] {3000, 3099},
314	        "QLD", new int[] {4000, 4099});
315	
316	    /**
317	     * Validate the optional postcode. Absent (null/empty) is valid — postcode is optional. When
318	     * present it must be exactly 4 digits; and when the owner's city maps to a known region (via the
319	     * mapper's fixed city-to-region table) it must fall inside that region's inclusive range
320	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit
321	     * postcode.
322	     */
323	    private boolean isPostcodeValid(Owner owner) {
324	        String postcode = owner.getPostcode();
325	        if (postcode == null || postcode.isEmpty()) {
326	            return true;
327	        }
328	        if (!postcode.matches("\\d{4}")) {
329	            return false;
330	        }
331	        int[] range = REGION_POSTCODE_RANGES.get(ownerMapper.cityRegion(owner));
332	        if (range == null) {
333	            return true;
334	        }
335	        int value = Integer.parseInt(postcode);
336	        return value >= range[0] && value <= range[1];
337	    }
338	
339	    /** Maximum number of owners permitted in a single city. */
340	    private static final int CITY_CAPACITY = 50;
341	
342	    /** Maximum number of owners that may be created (by registrationDate) on a single day. */
343	    private static final int DAILY_CREATE_LIMIT = 100;
344	
345	    /** Number of owners already created on a day beyond which a bulk-signup warning is flagged. */
346	    private static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
347	
348	    /**
349	     * Count the existing owners whose city matches this owner's city, compared case-insensitively.
350	     * Used to enforce the per-city capacity on create (before this owner is saved).
351	     */
352	    private int cityOwnerCount(Owner owner) {
353	        String city = owner.getCity();
354	        int count = 0;
355	        for (Owner existing : this.clinicService.findAllOwners()) {
356	            if (city != null && city.equalsIgnoreCase(existing.getCity())) {
357	                count++;
358	            }
359	        }
360	        return count;
361	    }
362	
363	    /**
364	     * Roll a registration date forward onto a business day: a Saturday or Sunday is advanced to the
365	     * following Monday, any weekday is returned unchanged. Applied to the effective registration date
366	     * (supplied or defaulted) so that everything derived from it — the stored {@code registrationDate},
367	     * the membership number's year segment and the per-day create limit — uses the adjusted date.
368	     */
369	    private static java.time.LocalDate toBusinessDay(java.time.LocalDate date) {
370	        switch (date.getDayOfWeek()) {
371	            case SATURDAY:
372	                return date.plusDays(2);
373	            case SUNDAY:
374	                return date.plusDays(1);
375	            default:
376	                return date;
377	        }
378	    }
379	
380	    /**
381	     * Count the existing owners whose registrationDate equals the given day. Used to enforce the
382	     * per-day create limit on create (before this owner is saved).
383	     */
384	    private int ownersRegisteredOn(java.time.LocalDate day) {
385	        int count = 0;
386	        for (Owner existing : this.clinicService.findAllOwners()) {
387	            if (day.equals(existing.getRegistrationDate())) {
388	                count++;
389	            }
390	        }
391	        return count;
392	    }
393	
394	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
395	    @Override
396	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
397	        HttpHeaders headers = new HttpHeaders();
398	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
399	        if (!isPostcodeValid(owner)) {
400	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
401	        }
402	        String telephone = toE164(owner.getTelephone());
403	        if (telephone == null || !hasValidNationalLength(telephone)) {
404	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
405	        }
406	        if (!normalizeEmail(owner)) {
407	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
408	        }
409	        String address = normalizeAddress(owner.getAddress());
410	        if (address.isEmpty()) {
411	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
412	        }
413	        owner.setAddress(address);
414	        owner.setTelephone(telephone);
415	        if (owner.getRegistrationDate() != null
416	            && owner.getRegistrationDate().isAfter(java.time.LocalDate.now())) {
417	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
418	        }
419	        java.time.LocalDate registrationDate = toBusinessDay(
420	            owner.getRegistrationDate() == null ? java.time.LocalDate.now() : owner.getRegistrationDate());
421	        int ownersRegisteredToday = ownersRegisteredOn(registrationDate);
422	        if (ownersRegisteredToday >= DAILY_CREATE_LIMIT) {
423	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
424	        }
425	        if (cityOwnerCount(owner) >= CITY_CAPACITY) {
426	            return new ResponseEntity<>(HttpStatus.CONFLICT);
427	        }
428	        List<Owner> householdMembers = householdMembers(owner);
429	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
430	        if (sharesHousehold && !householdMembers.isEmpty()) {
431	            owner.setHouseholdId(householdMembers.stream()
432	                .map(Owner::getHouseholdId)
433	                .filter(id -> id != null && !id.isBlank())
434	                .findFirst()
435	                .orElseGet(() -> householdIdFor(owner)));
436	        }
437	        // Consolidated duplicate detection: the former separate telephone, email and household
438	        // checks are now all expressed through the single derived identityKey, so a new owner is
439	        // rejected only when its WHOLE identityKey equals an existing owner's. Because the telephone
440	        // is part of the key, two members of the same household with different telephones have
441	        // different identityKeys and are both allowed.
442	        String identityKey = owner.getIdentityKey();
443	        for (Owner existing : this.clinicService.findAllOwners()) {
444	            if (identityKey.equals(existing.getIdentityKey())) {
445	                return new ResponseEntity<>(HttpStatus.CONFLICT);
446	            }
447	        }
448	        if (owner.getHouseholdId() != null) {
449	            for (Owner member : householdMembers) {
450	                if (member.getHouseholdId() == null || member.getHouseholdId().isBlank()) {
451	                    member.setHouseholdId(owner.getHouseholdId());
452	                    this.clinicService.saveOwner(member);
453	                }
454	            }
455	        }
456	        owner.setNamesakeCount(namesakeCount(owner));
457	        owner.setHouseholdSize(householdMembers.size() + 1);
458	        owner.setBulkSignupWarning(ownersRegisteredToday > BULK_SIGNUP_WARNING_THRESHOLD);
459	        owner.setRegistrationDate(registrationDate);
460	        owner.setCustomerCode(customerCodeFor(owner));
461	        this.clinicService.saveOwner(owner);
462	        AUDIT.info("owner created id={} customerCode={} registrationDate={}",
463	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate());
464	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
465	        headers.setLocation(UriComponentsBuilder.newInstance()
466	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
467	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
468	    }
469	
470	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
471	    @Override
472	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
473	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
474	        if (currentOwner == null) {
475	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
476	        }
477	        currentOwner.setAddress(ownerFieldsDto.getAddress());
478	        currentOwner.setCity(ownerFieldsDto.getCity());
479	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
480	        currentOwner.setLastName(ownerFieldsDto.getLastName());
481	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
482	        currentOwner.setEmail(ownerFieldsDto.getEmail());
483	        if (!normalizeEmail(currentOwner)) {
484	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
485	        }
486	        this.clinicService.saveOwner(currentOwner);
487	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
488	    }
489	
490	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
491	    @Transactional
492	    @Override
493	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
494	        Owner owner = this.clinicService.findOwnerById(ownerId);
495	        if (owner == null) {
496	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
497	        }
498	        this.clinicService.deleteOwner(owner);
499	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
500	    }
501	
502	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
503	    @Override
504	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
505	        Owner owner = this.clinicService.findOwnerById(ownerId);
506	        if (owner == null) {
507	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
508	        }
509	        HttpHeaders headers = new HttpHeaders();
510	        Pet pet = petMapper.toPet(petFieldsDto);
511	        owner.setId(ownerId);
512	        pet.setOwner(owner);
513	        pet.getType().setName(null);
514	        this.clinicService.savePet(pet);
515	        PetDto petDto = petMapper.toPetDto(pet);
516	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
517	            .buildAndExpand(pet.getId()).toUri());
518	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
519	    }
520	
521	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
522	    @Override
523	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
524	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
525	        if (currentOwner != null) {
526	            Pet currentPet = this.clinicService.findPetById(petId);
527	            if (currentPet != null) {
528	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
529	                currentPet.setName(petFieldsDto.getName());
530	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
531	                this.clinicService.savePet(currentPet);
532	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
533	            }
534	        }
535	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
536	    }
537	
538	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
539	    @Override
540	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
541	        HttpHeaders headers = new HttpHeaders();
542	        Visit visit = visitMapper.toVisit(visitFieldsDto);
543	        Pet pet = new Pet();
544	        pet.setId(petId);
545	        visit.setPet(pet);
546	        this.clinicService.saveVisit(visit);
547	        VisitDto visitDto = visitMapper.toVisitDto(visit);
548	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
549	            .buildAndExpand(visit.getId()).toUri());
550	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
551	    }
552	
553	
554	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
555	    @Override
556	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
557	        Owner owner = this.clinicService.findOwnerById(ownerId);
558	        if (owner != null) {
559	            Pet pet = owner.getPet(petId);
560	            if (pet != null) {
561	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
562	            }
563	        }
564	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
565	    }
566	}
